import threading

class UnitOfWork:
    def __init__(self, metadata=None, timeout=None):
        self.metadata = metadata or {}
        self.timeout = timeout
        self.lock = threading.Lock()
        self.transaction = None
        self.result = None

    def __call__(self, func):
        def wrapper(*args, **kwargs):
            with self.lock:
                if self.transaction:
                    print("Transaction is already active, creating a new one")
                    self.submit()
                self.transaction = func(*args, **kwargs)
                self.submit()
            return self.result

        return wrapper

    def submit(self):
        with self.lock:
            if self.transaction is None:
                raise RuntimeError("No active transaction")
            if self.timeout is not None:
                self.transaction = self.transaction.execute(config={'timeout': self.timeout})
            if self.metadata:
                self.transaction = self.transaction.execute(config={'metadata': self.metadata})
            self.result = self.transaction.results[0][0] if self.transaction.results else None
