def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    result = []
    for arg in cmd:
        # Check if the argument is a shebang
        if arg.startswith('#!'):
            # Split the shebang and the rest of the argument
            shebang, rest = arg.split(None, 1)
            # Fix the path if it's a deep path shebang
            if rest.startswith('"') and rest.endswith('"') and rest[1:-1].startswith('/'):
                result.append('#!' + rest[1:-1].replace('/', '\\') + '\n' + rest[-1])
            else:
                result.append('#!' + rest)
        else:
            result.append(arg)
    return tuple(result)
