    result = f"{e.__class__.__name__} at {e.__file__}:{e.__lineno__} "

    if max_level == 0:
        return result

    level = 0
    stack = inspect.stack()
    for frame, filename, lineno, func_name, line,locals in reversed(stack[:max_level]):
        if level >= max_path_level:
            break
        result += f"{func_name} in {filename}:{lineno} \t"
        level += 1

