def extostr(e, max_level=30, max_path_level=5) -> str:
    stack = [e]
    paths = {}
    depth = 0

    while stack:
        current = stack.pop(0)
        if current not in paths:
            paths[current] = {"level": depth, "value": current}

        if depth < max_level:
            stack.extend(child for child in current.children if child not in paths)

        if depth < max_path_level:
            parents = [parent for parent in current.parents if parent not in paths]
            if parents:
                stack.insert(0, parents[-1])

        depth += 1

    return "\n".join(f"{depth}.{value}" for depth, value in paths.values())
