    # Helper function to find the minimum base class
    def find_min(num):
        for i in range(1, int(log2(num)) + 1):
            if num & (1 << i) != 0:
                return i
        return 0

    # Find the minimum base class for each class in the input list
    minimal_classes = [find_min(cls) for cls in classes]

    # Return the minimum base classes
    return minimal_classes
