def _extract_number_and_supplment_from_issue_element(issue):
    match = re.search('<issue>(.*?)</issue>', issue)
    if match:
        numbers_suppliments = match.group(1).split()
        numbers = [n for n in numbers_suppliments if re.match(r'\d+', n)]
        supplements = [s for s in numbers_suppliments if re.match(r'[a-zA-Z ]+', s)]
        return numbers, supplements
