def deep_merge_nodes(nodes: List[Tuple[Union, Union]]) -> List[Tuple[Union, Union]]:
    merged_result = []
    for node_key, node_value in nodes:
        # If the key appears multiple times, combine the values into a list
        if node_key in [item[0] for item in merged_result]:
            existing_node = next(item for item in merged_result if item[0] == node_key)
            existing_node[1].append(node_value)
        else:
            merged_result.append((node_key, [node_value]))  # Each key can map to multiple values
    return merged_result
