from typing import Set, Optional

def find_roots(
    graph: Graph, prop: URIRef, roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    stack = [node for node in graph.subjects(predicate=prop) if node not in roots]
    while stack:
        node = stack.pop()
        if node not in roots:
            roots.add(node)
            stack.extend(graph.predecessors(node))
    return roots
