import subprocess
def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    cmd = ['ansible-playbook']
    if verbose:
        cmd.append('-v')
    if extra_vars:
        cmd.extend(['--extra-vars', '='.join(extra_vars.items())])
    if ansible_args:
        cmd.extend([f'--{k}', str(v)] for k, v in ansible_args.items())
    cmd.append(playbook_path)
    process = subprocess.run(cmd, capture_output=True, text=True)
    if process.returncode != 0:
        raise Exception(f'Ansible playbook failed with exit code {process.returncode}')
    return process.stdout
